        return -1;
    }
    dist: dict[str, int] = {};
    dist[src] = 0;
    if src == dst {
        return 0;
    }
    frontier: list[Person] = [start];
    depth = 0;
    while len(frontier) > 0 {
        depth += 1;
        frontier = _expand(frontier, dist, depth);
        if dst in dist {
            return dist[dst];
        }
    }
