"""Entity resolution: transitive connectivity over shared attributes.

Accounts are linked *transitively* through shared attribute values
(shared email, shared phone): records sharing a value in ANY link field
belong to one entity. The resolver buckets records by ``(field, value)``,
expands the buckets into an adjacency map, and floods each component;
each record is tagged with its entity id. Blank or missing link values
must NEVER merge two records -- absence of an email is not a shared
email. Entity id = smallest record id in the component.
Ref: pratapram/dale#24
"""


def resolve_entities(records, link_fields):
    """``records``: dicts with an ``id`` key. Returns {record_id: entity_id}."""
    buckets = {}
    for rec in records:
        for field in link_fields:
            value = rec.get(field)
            if value is None or value == "":
                continue  # blank values never merge
            key = (field, value)
            if key not in buckets:
                buckets[key] = []
            buckets[key].append(rec["id"])

    adj = {rec["id"]: [] for rec in records}
    for ids in buckets.values():
        for a in ids:
            for b in ids:
                if a != b:
                    adj[a].append(b)

    label = {}
    for rec in records:
        rid = rec["id"]
        if rid in label:
            continue
        # flood the whole component; entity id = min member id
        comp = []
        seen = {rid}
        stack = [rid]
        while stack:
            cur = stack.pop()
            comp.append(cur)
            for nxt in adj[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        entity = min(comp)
        for member in comp:
            label[member] = entity
    return label
```

"""Entity resolution over shared attributes, lifted to OSP.

The bucket map and expanded adjacency become an alternating typed graph:
Record nodes --HasValue--> ValueNode --ValueOf--> Record. Component
labeling becomes one flooding walker per unresolved component sharing a
claim map across spawns (the cycle policy -- jac walkers do not dedupe,
so every record/value key is guarded once). Entity id stays min(record
id) per component, so results are order-independent.
Ref: pratapram/dale#24
"""
node Record {
    has rkey: str;
}
node ValueNode {
    has vkey: str;
}
edge HasValue {}  # record -> shared attribute value
edge ValueOf {}   # value -> member record

obj Resolver {
    has records: dict;
    has values: dict;
    has order: list;
}

walker LabelFlood {
    # Cycle policy: claim-once across BOTH node kinds, shared by all
    # spawns of one component sweep.
    has claimed: dict[str, bool] = {};
    has members: list[str] = [];
    has best_id: int = -1;

    can step_record with Record entry {
        if here.rkey in self.claimed {
            skip;
        }
        self.claimed[here.rkey] = True;
        self.members.append(here.rkey);
        rid = int(here.rkey[2:]);
        if self.best_id < 0 or rid < self.best_id {
            self.best_id = rid;
        }
        visit [->:HasValue:->];
    }

    can step_value with ValueNode entry {
        k = "v:" + here.vkey;
        if k in self.claimed {
            skip;
        }
        self.claimed[k] = True;
        visit [->:ValueOf:->];
    }
}

"""Resolve ``records`` into entities linked through ``link_fields``.

Records sharing a non-blank value in any link field are transitively one
entity; blank or missing values never merge. Returns {record_id: entity_id}
with entity_id = smallest record id in the component.
"""
def resolve_entities(records: list, link_fields: list) -> dict {
    res = Resolver(records={}, values={}, order=[]);
    for rec in records {
        rkey = f"r:{rec['id']}";
        if rkey not in res.records {
            n = Record(rkey=rkey);
            root ++> n;
            res.records[rkey] = n;
            res.order.append(rkey);
        }
    }
    for rec in records {
        rkey = f"r:{rec['id']}";
        for f in link_fields {
            val = rec.get(f);
            # Blank values NEVER merge: absence of an email is not a
            # shared email (the issue's most-likely correctness bug).
            if val is not None and val != "" {
                vkey = f"{f}:{val}";
                if vkey not in res.values {
                    vn = ValueNode(vkey=vkey);
                    root ++> vn;
                    res.values[vkey] = vn;
                }
                res.records[rkey] +>:HasValue:+> res.values[vkey];
                res.values[vkey] +>:ValueOf:+> res.records[rkey];
            }
        }
    }
    labels: dict = {};
    claimed: dict[str, bool] = {};
    for rkey in res.order {
        if rkey in claimed {
            continue;
        }
        start: Record = res.records[rkey];
        w = start spawn LabelFlood(claimed=claimed);
        ent = w.best_id;
        for mk in w.members {
            labels[int(mk[2:])] = ent;
        }
    }
    return labels;
}

