"""ELares/IronTraffic#147 — Reverse dependency dirty propagation for incremental compile."""

node Unit { has uid: str; }
edge UpstreamOf {}

obj CompileGraph {
    has units: dict[str, Unit] = {};
    has dirty: dict[str, bool] = {};
}

walker ReverseWalk {
    has claimed: dict[str, bool] = {};
    has reached: list[str] = [];

    can step with Unit entry {
        if here.uid in self.claimed { skip; }
        self.claimed[here.uid] = True;
        self.reached.append(here.uid);
        visit [->:UpstreamOf:->][?:Unit];
    }
}

def load_compile_graph(units: list[str], depends: list[tuple[str, str]]) -> CompileGraph {
    g = CompileGraph();
    for uid in units {
        nd = Unit(uid=uid);
        root ++> nd;
        g.units[uid] = nd;
    }
    for (upstream, downstream) in depends {
        u = g.units.get(upstream, None);
        d = g.units.get(downstream, None);
        if u is not None and d is not None { u +>:UpstreamOf:+> d; }
    }
    return g;
}

def reverse_dependents(graph: CompileGraph, unit_id: str) -> list[str] {
    nd = graph.units.get(unit_id, None);
    if nd is None { return []; }
    w = nd spawn ReverseWalk(claimed={}, reached=[]);
    return sorted(w.reached);
}

def mark_dirty(graph: CompileGraph, changed: list[str]) -> list[str] {
    dirty: dict[str, bool] = {};
    for uid in changed {
        if not (uid in graph.units) { continue; }
        for dep in reverse_dependents(graph, uid) {
            dirty[dep] = True;
        }
    }
    graph.dirty = dirty;
    out: list[str] = [];
    for k in dirty.keys() { out.append(k); }
    return sorted(out);
}

def is_dirty(graph: CompileGraph, unit_id: str) -> bool {
    return graph.dirty.get(unit_id, False);
}

"""DNS wire hierarchy lifted to OSP.

Domains are ``Domain`` nodes; ``PartOf`` edges point from a domain
to its parent zone. FQDN construction and zone chains climb; delegated
subdomain counts descend. Zone flags are payload the chain query
must respect.
"""

node Domain {
    has label: str;
    has is_zone: bool;
    has del_total: int = 0;  # staging: delegations below, folded at exit
}

edge PartOf: Domain --> Domain {}

"""Build the fixture zone tree deterministically; returns the root zone."""
def build_zones() -> Domain {
    root ++> (dns_root := Domain(label="", is_zone=True));
    root ++> (com := Domain(label="com", is_zone=True));
    root ++> (example := Domain(label="example", is_zone=True));
    root ++> (api := Domain(label="api", is_zone=False));
    root ++> (v1 := Domain(label="v1", is_zone=False));
    root ++> (org := Domain(label="org", is_zone=False));
    com +>:PartOf:+> dns_root;
    example +>:PartOf:+> com;
    api +>:PartOf:+> example;
    v1 +>:PartOf:+> api;
    org +>:PartOf:+> dns_root;
    return dns_root;
}

"""Delegate `label` under `parent` (None for the root zone); return it."""
def register(parent: Domain | None, label: str, is_zone: bool = False) -> Domain {
    root ++> (d := Domain(label=label, is_zone=is_zone));
    if parent is not None {
        d +>:PartOf:+> parent;
    }
    return d;
}

walker FqdnClimb {
    """Climbs PartOf edges to the root zone; linear walk."""
    has labels: list[str] = [];
    has zones: list[bool] = [];
    has claimed: dict[str, bool] = {};

    can climb with Domain entry {
        if here.label in self.claimed {
            skip;
        }
        self.claimed[here.label] = True;
        self.labels.append(here.label);
        self.zones.append(here.is_zone);
        visit [->:PartOf:->] else { report self.labels; disengage; }
    }
}

walker DelFold {
    """Exit folds strictly-below delegation counts bottom-up."""
    has claimed: dict[str, bool] = {};

    can descend with Domain entry {
        if here.label in self.claimed {
            skip;
        }
        self.claimed[here.label] = True;
        visit [<-:PartOf:<-];
    }

    can fold with Domain exit {
        total = 0;
        for s in [<-:PartOf:<-] {
            total += 1 + s.del_total;
        }
        here.del_total = total;
    }
}

"""Fully qualified name of `d`, built by ascending to the root."""
def fqdn(d: Domain) -> str {
    w = d spawn FqdnClimb();
    return "".join([lab + "." for lab in reversed(w.labels)]);
}

"""Zone names on the path to the root, nearest zone first."""
def zone_chain(d: Domain) -> list[str] {
    w = d spawn FqdnClimb();
    picked = [w.labels[i] for i in range(len(w.labels)) if w.zones[i]];
    return picked;
}

"""Delegated domains strictly below `zone`."""
def subdomain_count(zone: Domain) -> int {
    zone spawn DelFold();
    return zone.del_total;
}

"""Hops from `d` up to the nearest enclosing zone host (itself counts)."""
def soa_distance(d: Domain) -> int {
    w = d spawn FqdnClimb();
    for i in range(len(w.zones)) {
        if w.zones[i] {
            return i + 1;
        }
    }
    return -1;
}

"""Reify construct-level dependencies into resource-level depends_on, lifted to OSP.

Constructs become Construct nodes; the children map becomes typed
Composition edges (parent -> child); construct-level addDependency
declarations become typed Depends edges. The manual stack sweep over the
children map becomes a walker descending Composition edges whose dead ends
ARE the leaf resources; crossing a Depends edge into the target subtree is
a fresh spawn of the same leaf walker at the target construct, so every
declaration cross-products its two leaf sets. Self pairs are skipped so a
dependency on an ancestor never makes a resource depend on itself. The
claim map is the cycle policy for diamond-shaped child lists; unknown
construct paths raise KeyError exactly like the source.
Ref: open-constructs/cdk-terrain#354
"""
node Construct {
    has path: str;
}
edge Composition {}
edge Depends {}

"""Loader handle: construct paths resolve through this lookup map."""
obj Model {
    has constructs: dict[str, Construct];

    def resolve(path: str) -> Construct | None {
        return self.constructs.get(path);
    }
}

"""Deterministic fresh-graph builder from a {path: [child paths]} tree spec."""
def load_model(tree: dict[str, list[str]], deps: list[tuple[str, str]]) -> Model {
    m = Model(constructs={});
    for path in tree.keys() {
        c = Construct(path=path);
        root ++> c;
        m.constructs[path] = c;
    }
    for path in tree.keys() {
        for kid in tree[path] {
            child = m.resolve(kid);
            if child is not None {
                m.constructs[path] +>:Composition:+> child;
            }
        }
    }
    for pair in deps {
        src = m.resolve(pair[0]);
        dst = m.resolve(pair[1]);
        if src is None {
            raise KeyError(pair[0]);
        }
        if dst is None {
            raise KeyError(pair[1]);
        }
        src +>:Depends:+> dst;
    }
    return m;
}

"""Leaf collector: descends Composition edges; a dead end IS a leaf resource."""
walker LeavesWalk {
    has claimed: dict[str, bool] = {};
    has leaves: list[str] = [];

    can step with Construct entry {
        # Cycle policy: one visit per construct regardless of path count.
        if here.path in self.claimed {
            skip;
        }
        self.claimed[here.path] = True;
        # a dead end IS a leaf resource; keep walking remaining branches
        visit [->:Composition:->] else { self.leaves.append(here.path); }
    }
}

"""Every leaf resource path beneath construct ``path``, sorted."""
def leaves_under(tree: dict[str, list[str]], path: str) -> list {
    m = load_model(tree, []);
    c = m.resolve(path);
    if c is None {
        raise KeyError(path);
    }
    w = c spawn LeavesWalk(claimed={}, leaves=[]);
    return sorted(w.leaves);
}

"""Reify construct-level dependencies into leaf-to-leaf depends_on."""
def synth_dependencies(tree: dict[str, list[str]], deps: list[tuple[str, str]]) -> dict {
    m = load_model(tree, deps);
    out: dict = {};
    # one subtree walk per declaration; crossing its Depends edges spawns
    # the leaf walker inside each target subtree (the N x M cross product)
    for pair in deps {
        src = m.resolve(pair[0]);
        if src is None {
            raise KeyError(pair[0]);
        }
        sw = src spawn LeavesWalk(claimed={}, leaves=[]);
        targets: list[Construct] = [src ->:Depends:->];
        for tgt in targets {
            tw = tgt spawn LeavesWalk(claimed={}, leaves=[]);
            for s_leaf in sw.leaves {
                for d_leaf in tw.leaves {
                    if s_leaf != d_leaf {
                        if s_leaf not in out {
                            out[s_leaf] = [];
                        }
                        if d_leaf not in out[s_leaf] {
                            out[s_leaf].append(d_leaf);
                        }
                    }
                }
            }
        }
    }
    for k in out.keys() {
        out[k] = sorted(out[k]);
    }
    return out;
}

