    """Everyone descending from ``person`` (inclusive), sorted once."""
    seen = {person}
    stack = [person]
    while stack:
        cur = stack.pop()
        for kid in fam["children"].get(cur, []):
            if kid not in seen:
                seen.add(kid)
                stack.append(kid)
    return sorted(seen)


def in_laws(fam, person):
