"""Deterministic fresh-graph builder; creation order = fixture order."""
def load_family(persons: list[str], relations: list[tuple[str, str, str]]) -> Family {
    fam = Family(people={}, names=[]);
    for p in persons {
        n = Person(name=p);
        root ++> n;
        fam.people[p] = n;
        fam.names.append(p);
    }
    for (kind, a, b) in relations {
        na = fam.people[a];
        nb = fam.people[b];
        if kind == "parent" {
            nb +>:ParentOf:+> na;
            na +>:ChildOf:+> nb;
        } elif kind == "spouse" {
            na +>:SpouseTo:+> nb;
            nb +>:SpouseTo:+> na;
        }
    }
    return fam;
