    if step not in store._steps:
        return []
    chain: list[str] = []
    cur: str | None = step
    seen: set[str] = set()
    while cur is not None:
        if cur in seen:
            break
        seen.add(cur)
        chain.append(cur)
        cur = store._steps.get(cur)
    return list(reversed(chain))


def reachable_via_spawn(store: PipelineStore, root: str) -> list[str]:
    if root not in store._steps:
        return []
    seen: set[str] = {root}
    queue: deque[str] = deque([root])
    while queue:
        cur = queue.popleft()
        for nxt in store._spawn_of.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return sorted(seen)


def ready_after_deps(store: PipelineStore, completed: list[str]) -> list[str]:
    done = set(completed)
    out: list[str] = []
