    q: deque[str] = deque([root_id])
    claimed: set[str] = set()
    hits: list[str] = []
    while q:
        cur = q.popleft()
        if cur in claimed:
            continue
        claimed.add(cur)
        hits.append(cur)
        for ch in g._children.get(cur, []):
            if ch not in claimed:
                q.append(ch)
    return sorted(hits)


def dependent_closure(g: PlannerGraph, task_id: str) -> list[str]:
    if task_id not in g._tasks:
        return []
    stack = [task_id]
    seen: set[str] = set()
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        stack.extend(g._dependents.get(cur, ()))
    return sorted(seen)
