    d.hire("ceo", "Chief")
    d.hire("cta", "Tech")
    d.hire("pm", "Product")
    assert d.assign("ceo", "cta") and d.assign("ceo", "pm")
    assert d.grant("cta", "repo") and d.grant("pm", "design")
    gone, n = d.offboard("ceo")
    print(gone, n, d.active_people(), d.holders_of("repo"))
