    if entry not in g.handlers:
        return []
    seen: set[str] = set()
    q: deque[str] = deque([entry])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in g.calls.get(cur, []):
            if nxt not in seen:
                q.append(nxt)
    return sorted(seen)


