    gate = chart_gate_status(open_blockers)
    kinds = store["kinds"]
    wf = 0
    doc = 0
    ex = 0
    gt = 0
    for tid in topo:
        k = kinds.get(tid, "")
        if k == KIND_WORKFLOW:
            wf += 1
        if k == KIND_DOCS:
            doc += 1
        if k == KIND_EXAMPLE:
            ex += 1
        if k == KIND_GATE:
            gt += 1
    return {
        "gate": gate,
        "direct": direct,
        "topology": topo,
        "topology_count": len(topo),
        "workflow_tasks": wf,
        "docs_tasks": doc,
        "example_tasks": ex,
        "gate_tasks": gt,
    }
