    }
    return sorted(out);
}

def affected_paths(
    g: DepGraph,
    changed: list[str],
    max_depth: int | None = None,
) -> list[str] {
    rows = affected_files(g, changed, max_depth);
    names: list[str] = [];
    for (f, _) in rows { names.append(f); }
    return sorted(names);
}

