        stack.add(node)
        for blk in g._blockers.get(node, []):
            if blk in stack:
                errors.append((blk, node))
            elif blk not in visited:
                dfs(blk)
        stack.remove(node)

    for tid in sorted(g._tickets):
        if tid not in visited:
            dfs(tid)
    return sorted(errors)


