    q: deque[tuple[str, int]] = deque((s, 0) for s in seeds if s in g._modules)
    seen: set[str] = set()
    while q:
        cur, depth = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        if depth >= max_depth:
            continue
        for rev in sorted(g._rev.get(cur, ())):
            if rev not in seen:
                q.append((rev, depth + 1))
    return seen


