        if cur in seen:
            continue
        seen.add(cur)
        out.add(cur)
        for ch in store._children.get(cur, []):
            stack.append(ch)
    return sorted(out)


def is_acyclic(store: LineageStore) -> bool:
    indeg = {n: len(store._parents.get(n, [])) for n in store._nodes}
    queue: deque[str] = deque([n for n in store._nodes if indeg[n] == 0])
    seen = 0
    while queue:
