    claimed: dict[str, bool] = {}
    order: list[str] = []
    list_calls = 0
    truncated = False
    queue: deque[str] = deque([start_id])
    nodes = _WALK_NODES
    while queue:
        sid = queue.popleft()
        if sid in claimed:
            continue
        if list_cap > 0 and list_calls >= list_cap:
            truncated = True
            break
