        return None
    if source == target:
        return [source]
    q: deque[tuple[str, list[str]]] = deque([(source, [source])])
    seen: set[str] = {source}
    while q:
        cur, path = q.popleft()
        if len(path) > max_depth:
            continue
        for nxt, etype in store._edges.get(cur, []):
            if not _allowed(etype, edge_types):
                continue
            if nxt in seen:
                continue
            npath = path + [nxt]
            if nxt == target:
                return npath
            seen.add(nxt)
            q.append((nxt, npath))
    return None


