def _tree_walk_ids(start_id: str, store: OutlineStore) -> list[str]:
    visited: set[str] = set()
    order: list[str] = []
    stack: list[str] = [start_id]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        order.append(cur)
        kids = sorted(store._children.get(cur, []))
        i = len(kids) - 1
        while i >= 0:
            stack.append(kids[i])
            i -= 1
    return order


