    done = set(finished)
    ready: list[str] = []
    for jid in sorted(g.jobs):
        if jid in done:
            continue
        needs = [p for p in critical_predecessors(g, jid) if p != jid]
        if all(p in done for p in needs):
            ready.append(jid)
    return ready
