    adj: dict[str, list[str]],
    meta: dict[str, dict[str, Any]],
    admitted: set[str],
) -> tuple[dict[str, list[str]], list[str]]:
    new_adj = {node: list(children) for node, children in adj.items()}
    flattened: list[str] = []
    for fid in sorted(meta):
