    segs: list[str] = [];
    i = len(w.parts) - 1;
    while i >= 0 {
        segs.append(w.parts[i]);
        i -= 1;
    }
    out = "";
    for s in segs {
        if len(out) > 0 {
            out += "/";
        }
        out += s;
    }
    return out;
