"""Dependency graph and impact analysis foundation, lifted to OSP.

Files, components, tasks, and tests become node archetypes; ownership,
dependence, and coverage become typed PartOf / DependsOn / Covers edges.
The chained reverse sweeps over dict-of-lists become a single walker over
typed edges: from each changed file it follows PartOf forward to the
owning components, then reverse DependsOn to every task depending on them,
then reverse Covers to the covering tests. The per-archetype claim map is
the cycle policy for diamonds (a task depending on two impacted components
is reached twice and reported once). A changed file owned by no component
dead-ends immediately, exactly like the source sweep.
Ref: thomascarter613/monad-workspace#165
"""
node File {
    has name: str;
}
node Component {
    has name: str;
}
node Task {
    has name: str;
}
node TestNode {
    has name: str;
}
edge PartOf {}
edge DependsOn {}
edge Covers {}

"""Loader handle: entity names resolve through these lookup maps."""
obj Model {
    has files: dict[str, File];
    has comps: dict[str, Component];
    has tasks: dict[str, Task];
    has tests: dict[str, TestNode];

    def resolve_file(name: str) -> File | None {
        return self.files.get(name);
    }
}

"""Deterministic fresh-graph builder from the {kind: {name: [rels]}} model."""
def load_model(model: dict) -> Model {
    m = Model(files={}, comps={}, tasks={}, tests={});
    comps_map: dict[str, list[str]] = model.get("components", {});
    tasks_map: dict[str, list[str]] = model.get("tasks", {});
    tests_map: dict[str, list[str]] = model.get("tests", {});
    for comp in comps_map.keys() {
        c = Component(name=comp);
        root ++> c;
        m.comps[comp] = c;
    }
    for comp in comps_map.keys() {
        owner = m.comps[comp];
        for fname in comps_map[comp] {
            f = m.resolve_file(fname);
            if f is None {
                f = File(name=fname);
                root ++> f;
                m.files[fname] = f;
            }
            f +>:PartOf:+> owner;
        }
    }
    for task in tasks_map.keys() {
        t = Task(name=task);
        root ++> t;
        m.tasks[task] = t;
        for dep in tasks_map[task] {
            dc = m.comps.get(dep);
            if dc is not None {
                t +>:DependsOn:+> dc;
            }
        }
    }
    for tst in tests_map.keys() {
        e = TestNode(name=tst);
        root ++> e;
        m.tests[tst] = e;
        for covered in tests_map[tst] {
            tk = m.tasks.get(covered);
            if tk is not None {
                e +>:Covers:+> tk;
            }
        }
    }
    return m;
}

"""Ripple walker: file -> components -> depending tasks -> covering tests."""
walker ImpactWalk {
    has claimed: dict[str, bool] = {};
    has comps: list[str] = [];
    has tasks: list[str] = [];
    has tests: list[str] = [];

    can on_file with File entry {
        # Cycle policy: one visit per file regardless of path count.
        if "f:" + here.name in self.claimed {
            skip;
        }
        self.claimed["f:" + here.name] = True;
        visit [->:PartOf:->];
    }

    can on_component with Component entry {
        if "c:" + here.name in self.claimed {
            skip;
        }
        self.claimed["c:" + here.name] = True;
        if here.name not in self.comps {
            self.comps.append(here.name);
        }
        visit [<-:DependsOn:<-];
    }

    can on_task with Task entry {
        if "t:" + here.name in self.claimed {
            skip;
        }
        self.claimed["t:" + here.name] = True;
        if here.name not in self.tasks {
            self.tasks.append(here.name);
        }
        visit [<-:Covers:<-];
    }

    can on_test with TestNode entry {
        if "e:" + here.name in self.claimed {
            skip;
        }
        self.claimed["e:" + here.name] = True;
        if here.name not in self.tests {
            self.tests.append(here.name);
        }
    }
}

"""Changed-file impact analysis: impacted components, tasks, and tests."""
def impacted(model: dict, changed_files: list) -> dict {
    m = load_model(model);
    comps: list[str] = [];
    tasks: list[str] = [];
    tests: list[str] = [];
    for fname in changed_files {
        f = m.resolve_file(fname);
        if f is None {
            continue;  # owned by no component: no impact, like the source
        }
        w = f spawn ImpactWalk(claimed={}, comps=[], tasks=[], tests=[]);
        for c in w.comps {
            if c not in comps {
                comps.append(c);
            }
        }
        for t in w.tasks {
            if t not in tasks {
                tasks.append(t);
            }
        }
        for e in w.tests {
            if e not in tests {
                tests.append(e);
            }
        }
    }
    return {"components": sorted(comps), "tasks": sorted(tasks), "tests": sorted(tests)};
}

"""Recommended verification for a change: tests covering impacted tasks."""
def recommend_tests(model: dict, changed_files: list) -> list {
    return impacted(model, changed_files)["tests"];
}

"""Dependency-graph collection, lifted to OSP.

Artifacts become Artifact nodes, dependency entries become typed Depends
edges, and both the crashing recursive accept walk and the iterative
work-stack walk collapse into one walker over typed edges: walkers do not
recurse, so the deep-chain stack overflow of the recursive collector cannot
occur, and the iterative remediation adds nothing to preserve. The
once-per-artifact claim map is the walk's cycle policy; output is
normalized to sorted artifact ids, matching the source contract.
Ref: apache/maven-dependency-tree#130
"""
node Artifact {
    has name: str;
}
edge Depends {}

"""Loader handle: artifact ids resolve through this lookup map."""
obj Tree {
    has arts: dict[str, Artifact];

    def resolve(name: str) -> Artifact | None {
        return self.arts.get(name);
    }
}

"""Deterministic fresh-graph builder from an {artifact: [deps]} spec."""
def load_tree(graph: dict[str, list[str]]) -> Tree {
    tree = Tree(arts={});
    names: set[str] = set(graph.keys());
    for k in graph.keys() { names = names | set(graph[k]); }
    for name in names {
        a = Artifact(name=name);
        root ++> a;
        tree.arts[name] = a;
    }
    for name in graph.keys() {
        for dep in graph[name] {
            if dep in tree.arts {
                tree.arts[name] +>:Depends:+> tree.arts[dep];
            }
        }
    }
    return tree;
}

walker CollectWalk {
    has claimed: dict[str, bool] = {};
    has order: list[str] = [];

    can step with Artifact entry {
        # Cycle policy: one visit per artifact regardless of path count.
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.order.append(here.name);
        # Plain visit: an else-disengage would kill the whole flooded walk
        # while unvisited siblings are still queued; dead ends just queue
        # nothing and the claim map terminates the walk.
        visit [->:Depends:->];
    }
}

"""Recursive-path facade: sorted dependency closure of ``root``."""
def collect(graph: dict[str, list[str]], `root: str) -> list {
    tree = load_tree(graph);
    r = tree.resolve(`root);
    if r is None {
        return [`root];  # unknown root: closure is the lone artifact
    }
    w = r spawn CollectWalk(claimed={}, order=[]);
    return sorted(w.order);
}

"""Iterative-path facade: same closure; the walker never recurses."""
def collect_iter(graph: dict[str, list[str]], `root: str) -> list {
    tree = load_tree(graph);
    r = tree.resolve(`root);
    if r is None {
        return [`root];  # unknown root: closure is the lone artifact
    }
    w = r spawn CollectWalk(claimed={}, order=[]);
    return sorted(w.order);
}

"""Number of artifacts in the dependency closure of ``root``."""
def count_nodes(graph: dict[str, list[str]], `root: str) -> int {
    return len(collect_iter(graph, `root));
}

