            continue
        stack = [(start, 0)]
        while stack:
            node, idx = stack[-1]
            if idx == 0:
                if state[node] == 1:
                    return True
                if state[node] == 2:
                    stack.pop()
                    continue
                state[node] = 1
            deps = store._deps.get(node, [])
            if idx < len(deps):
                stack[-1] = (node, idx + 1)
                stack.append((deps[idx], 0))
            else:
                state[node] = 2
                stack.pop()
    return False


def ready_tasks(store: TaskGraph) -> list[str]:
    out: list[str] = []
    for t in sorted(store._tasks):
        if t in store._done:
            continue
        blockers = store._deps.get(t, [])
        if all(b in store._done for b in blockers):
