from __future__ import annotations


class ImportGraph:
    def __init__(self) -> None:
        self._nodes: set[str] = set()
        self._pred: dict[str, set[str]] = {}
        self._rev: dict[str, set[str]] = {}
        self._tests: set[str] = set()


def load_import_graph(
    files: list[str],
    deps: list[tuple[str, str]],
    tests: list[str],
) -> ImportGraph:
