from __future__ import annotations


class ProcessStore:
    def __init__(self) -> None:
        self._parent: dict[int, int | None] = {}
        self._cmdline: dict[int, str] = {}


def load_processes(rows: list[tuple[int, int | None, str]]) -> ProcessStore:
