    # BFS limited to exactly k hops via queue walk (hand-rolled)
    if start not in g.nodes:
        return set()
    cur: set[str] = {start}
    for _ in range(k):
        nxt: set[str] = set()
        for n in cur:
            for nb in g.adj.get(n, []):
                nxt.add(nb)
        cur = nxt
        if not cur:
            break
    return cur

