    visited: set[str] = set()
    stack: set[str] = set()
    def dfs(n: str) -> bool:
        visited.add(n)
        stack.add(n)
        for nb in g.adj.get(n, []):
            if nb not in visited:
                if dfs(nb):
                    return True
            elif nb in stack:
                return True
        stack.remove(n)
        return False
    for n in list(g.nodes):
        if n not in visited:
            if dfs(n):
                return True
    return False
