    """True when ``tag_b`` sits anywhere inside ``tag_a``'s pact web."""
    if tag_a not in net or tag_b not in net:
        return False
    seen = {tag_a}
    queue = deque([tag_a])
    while queue:
        cur = queue.popleft()
