        """Explicit stack walk over the children adjacency dict."""
        out = []
        stack = [root_id]
        seen = set()
        while stack:
            cur = stack.pop()
            if cur in seen:
                continue  # cycle guard on corrupt data
            seen.add(cur)
            out.append(cur)
            for ch in self.children_of.get(cur, []):
                stack.append(ch)
