        nesting depth), returned as list of lists.
        """
        levels = [[root_id]]
        frontier = [root_id]
        seen = {root_id}
        while frontier:
            nxt = []
            for cur in frontier:
                for ch in self.children_of.get(cur, []):
                    if ch in seen:
                        continue
                    seen.add(ch)
                    if ch in self.restricted:
                        continue  # hidden entirely: prune here
                    nxt.append(ch)
            if nxt:
                levels.append(nxt)
            frontier = nxt
        return levels

