    if start not in g._contacts:
        return []
    seen: set[str] = {start}
    q: deque[tuple[str, int]] = deque([(start, 0)])
    while q:
        cur, depth = q.popleft()
        if depth >= max_hops:
            continue
        for nb in g._links.get(cur, []):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, depth + 1))
    seen.discard(start)
    return sorted(seen)


