    if start not in g._contacts or end not in g._contacts:
        return None
    if start == end:
        return 0
    seen: set[str] = {start}
    q: deque[tuple[str, int]] = deque([(start, 0)])
    while q:
        cur, depth = q.popleft()
        for nb in g._links.get(cur, []):
            if nb == end:
                return depth + 1
            if nb not in seen:
                seen.add(nb)
                q.append((nb, depth + 1))
    return None


