        }
    }
    count = 0;
    names: list[str] = [];
    for k in tx.projects.keys() {
        names.append(k);
    }
    for p in names {
        eff = effective_tags(tx, p);
        for e in eff {
            if e in fam.keys() {
                count += 1;
                break;
            }
        }
    }
    return count;
}

