    out: list[str] = [];
    for sid in sorted(self.stages) {
        if sid in stages_done {
            continue;
        }
        ok = True;
        for pre in self.preds.get(sid, []) {
            if pre not in stages_done {
                ok = False;
            }
        }
        if ok {
