    queue: deque[str] = deque([root])
    while queue:
        cur = queue.popleft()
        for nxt in graph._spawns.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return sorted(seen)


def spawn_depth_within(graph: TaskGraph, root: str, limit: int) -> bool:
    if root not in graph._tasks:
        return False
    depth: dict[str, int] = {root: 0}
    queue: deque[str] = deque([root])
    while queue:
        cur = queue.popleft()
        for nxt in graph._spawns.get(cur, []):
            nd = depth[cur] + 1
            if nd > limit:
                return False
            if nxt not in depth or nd > depth[nxt]:
                depth[nxt] = nd
                queue.append(nxt)
    return True


